import{_ as s,h as i,i as t,c as l,v as e,p as o,x as r,m as E,e as c,S as u}from"./chunks/framework.Dvtg8yj2.js";const g=JSON.parse('{"title":"难度分层与课程","description":"","frontmatter":{"title":"难度分层与课程","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/instruction-curriculum.md","filePath":"llm/instruction-curriculum.md","lastUpdated":1788454257000}'),A={name:"llm/instruction-curriculum.md"};function p(h,a,d,m,B,S){const n=i("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="难度分层与课程" tabindex="-1">难度分层与课程 <a class="header-anchor" href="#难度分层与课程" aria-label="Permalink to &quot;难度分层与课程&quot;">​</a></h1><div class="epigraph"><p>指令数据没有自然的时间顺序；所谓课程，只是人为规定先见到哪些条件分布，以免一开始就把梯度交给最长、最怪的那一条。</p><footer>—— 课程学习的一般想法对照 Bengio 等人的 Curriculum Learning；指令侧的实践锚定 InstructGPT 的示范阶段、LIMA 的精选，以及 Self-Instruct 合成后必须再分层，而不是假定生成器已按难度出题</footer></div><p>预训练可以按文档质量或长度粗排，但更多时候是充分打乱。SFT 数据量小、方差大：有的样本是「把这句话翻译成英文」，有的是带五条约束的多轮改写加工具 JSON。若随机打乱且学习率相对指令损失仍然偏大，早期更新会被长样本与难推理主导，模型还没学会角色格式，就已经在拟合零星的思维链套话。课程学习（curriculum learning）在一般监督学习里的主张很朴素：先易后难，使优化走在更平滑的序列上。Bengio 等人 2009 年把它写成一种训练策略，而不是一种新损失。指令微调没有一篇与 InstructGPT、DPO 同等级的「必须按课程训」的定理；本篇只讨论<strong>难度代理怎么选</strong>、<strong>先对齐格式还是先堆推理</strong>、以及课程与预训练打乱策略差在哪里。不伪造一篇不存在的指令课程论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「难」在指令里不是标签。没有官方的年级，也没有像 ImageNet 那样的类间难度。Self-Instruct 生成时，模型喜欢产出中等长度、看起来复杂、实际是套模板的题面，「表面上难」会污染任何自动难度分。人写数据里，标注员示范（InstructGPT）往往中等规范，LIMA 精选则有意跨风格，短答案与长教程混在一起，若按 token 数排序，会把「难」定义成长，把短而密的好示范排到最后甚至挤出窗口。</p><p>随机打乱的代价是非平稳。一个 batch 里同时出现：格式尚未学会时的工具调用、需要保持人格的多轮、小学算术、以及安全拒答。梯度是这些方向的平均，早期参数会被最长的思维链拉走。这与 <a href="/llm/sft-forgetting">遗忘</a> 相关：不是旧知识被擦掉，而是新的条件分布还没立住，已经被少数高损失样本定义成「助手=长推理」。产品表现是简单题也啰嗦，难题仍然错。</p><h3 id="难度代理-长度、约束数、推理步、轮次" tabindex="-1">难度代理：长度、约束数、推理步、轮次 <a class="header-anchor" href="#难度代理-长度、约束数、推理步、轮次" aria-label="Permalink to &quot;难度代理：长度、约束数、推理步、轮次&quot;">​</a></h3><p>可用的标量代理包括：渲染后的 token 长度；用户轮里显式约束的条数（「必须 / 不要 / 用 JSON」）；是否要求逐步推导；对话轮次；是否含代码或工具 schema；语言相对于基座预训练是否低资源。任一代理都有失败模式。长度把啰嗦教师（OpenHermes 里常见的 GPT-4 长答）当成难，把 LIMA 里干净的短答当成易——后者往往对格式学习更重要。约束数依赖关键词，口语化用户（ShareGPT）会少用「必须」，并不等于简单。推理步若用「让我们逐步」来数，会把教师套话当成难例。因此分层应<strong>多信号投票</strong>，并抽检每个桶，而不是信一个分类器分数。</p><p><span class="marginnote">不要用教师模型对回答的损失当难度。教师对套话损失低、对罕见正确推导损失高，排序会把该学的难例当噪声丢掉。执行类任务（代码跑通、公式可解析）比损失更接近「难而不错」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一种与现有文献相容、又不声称来自某篇指令课程论文的做法是两段，而不是光滑的五十级。<strong>第一段：格式与短示范。</strong> 角色模板、短问答、单轮、低约束、含明确结束。数据以 InstructGPT 式示范与 LIMA 式精选为主，合成只取过滤后的短样本。目标是把 \\(p_\\theta(y\\mid x_{\\mathrm{chat}})\\) 从基座续写拉开，学会停、学会不当用户。<strong>第二段：覆盖与难度。</strong> 再放入多约束、多轮、长推理、工具、ShareGPT 真实追问、Self-Instruct 扩出来的领域网格。两段可以是两个物理阶段（换数据集继续训），也可以是同一日程里提高难例采样率。后者更接近「课程」，前者更像 InstructGPT「先 SFT 再偏好」那种阶段划分的微缩版——但第二段仍是 SFT，不是 RL。</p><p>桶内仍应打乱，以免同一模板连续出现。跨桶的课程只规定桶的混合比随步数变化，例如线性提高长样本与多轮的 \\(\\lambda\\)。安全样本不要全部留到最后：否则前段学成「有求必应」，后段再灌拒绝，容易过拟合拒答套话，或前段已经把有害配合写入（见 <a href="/llm/sft-safety-mix">安全配比</a>）。安全应在两段都按固定下限出现。</p>',12)),(t(),o(u,null,{default:r(()=>[c(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%8C%87%E4%BB%A4%E6%B1%A0%22%5D%20--%3E%20P%5B%22%E5%A4%9A%E4%BF%A1%E5%8F%B7%E6%89%93%E5%88%86%EF%BC%9A%E9%95%BF%E5%BA%A6%20%2F%20%E7%BA%A6%E6%9D%9F%20%2F%20%E8%BD%AE%E6%AC%A1%20%2F%20%E8%83%BD%E5%90%A6%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20E%5B%22%E6%98%93%E6%A1%B6%EF%BC%9A%E7%9F%AD%E3%80%81%E5%8D%95%E8%BD%AE%E3%80%81%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20P%20--%3E%20H%5B%22%E9%9A%BE%E6%A1%B6%EF%BC%9A%E5%A4%9A%E7%BA%A6%E6%9D%9F%E3%80%81%E5%A4%9A%E8%BD%AE%E3%80%81%E9%95%BF%E6%8E%A8%E7%90%86%22%5D%0A%20%20E%20--%3E%20S1%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%EF%BC%9A%E7%AB%8B%E4%BD%8F%20chat%20%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%EF%BC%9A%E6%8F%90%E9%AB%98%E9%9A%BE%E6%A1%B6%E9%87%87%E6%A0%B7%E7%8E%87%22%5D%0A%20%20H%20--%3E%20S2%0A%20%20SAF%5B%22%E5%AE%89%E5%85%A8%E6%A0%B7%E6%9C%AC%E4%B8%8B%E9%99%90%22%5D%20--%3E%20S1%0A%20%20SAF%20--%3E%20S2%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>Self-Instruct 合成之后必须再分层。生成器不会按你的课程出题；它按提示词出题。应对合成结果做与人写数据相同的代理打分，把「假难」（长而空）降权，把「真难且可检验」上采样。OpenHermes 这类汇编若直接当第二段，会跳过格式期，小模型上表现为套话先于遵循。ShareGPT 多轮天然偏难（历史长），宜截断策略正确后再进第二段，不要在模型还不会单轮停止时就喂十五轮。</p><h3 id="先易后难还是先对齐格式" tabindex="-1">先易后难还是先对齐格式 <a class="header-anchor" href="#先易后难还是先对齐格式" aria-label="Permalink to &quot;先易后难还是先对齐格式&quot;">​</a></h3><p>「易」应定义成<strong>格式上靠近产品、内容上靠近基座已会</strong>。翻译、摘要、简单改写对强基座是易的，对它们做 SFT 主要是套模板。数学竞赛证明对基座可能是难的，过早大量进入会让损失被个别符号错误支配。LIMA 的一千条并不是按难度排的课程，而是一张覆盖风格的静态集；它能工作，说明在强基座、高质量、短日程下，<strong>静态多样混合物</strong>往往够用，课程不是必要条件。课程在这些条件放松时才值得做：小模型、合成噪声大、样本长度方差极大、或必须在同一次 SFT 里塞进工具 JSON。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>课程改变的是优化路径上经验测度的序列 \\(p_t(x,y)\\)，而不是最终若充分混合、充分训练会收敛到的同一个全局极小——SFT 高度非凸且早停，路径即结果。早期 \\(p_t\\) 若由短格式样本主导，词头先学会角色标记与结束符，损失面相对平滑。随后提高难例，条件前缀已经是 chat，长推理的梯度是在「已经会当助手」的流形上走，而不是一边学 <code>&lt;|im_start|&gt;</code> 一边学证明。这与 Bengio 等人讨论的「先让决策边界在简单样本上立住」同构，只是简单样本在这里是短指令而不是低噪图像。</p><p>若反向课程（先极难），早期梯度范数被长序列主导，有效学习率相对短样本过大，短样本提供的格式信号被淹没。随机混合介于两者之间：期望上每种样本都会见到，但小数据+少步数时，谁先被抽到成为运气。课程是把运气换成明确的混合比日程。</p><p><span class="marginnote">按损失排序当课程（高损失先学或后学）会与教师套话耦合：套话损失低，被当成「已学会」跳过，模型永远不纠正谄媚。按损失课程只适用于同一分布、标签可靠的设定。指令合成不满足。</span></p><h3 id="与预训练课程的差别" tabindex="-1">与预训练课程的差别 <a class="header-anchor" href="#与预训练课程的差别" aria-label="Permalink to &quot;与预训练课程的差别&quot;">​</a></h3><p>预训练 token 以十亿计，打乱的目的是让每个窗口近似 i.i.d.，避免连续文档造成的相关梯度。SFT 步数少，i.i.d. 假设不重要，<strong>谁先塑造词头</strong>更重要。把预训练那套「充分 shuffle、恒定混合比」原样搬到 SFT，在数据已经清洗、长度相近、模型够强时（LIMA 设定）通常没问题；在 OpenHermes+ShareGPT 直接倒进小模型时，词头会被最长教师回答写定。另一差别是：预训练课程若按质量，丢掉的是低质量网页；指令课程若按难度，<strong>不能丢掉难例</strong>，只能晚一点见到，否则覆盖目标失败。Self-Instruct 扩出来的难领域若被「易」过滤器永久删掉，课程就退化成了又一次过度清洗。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有公开的 InstructGPT 公式说他们按难度排序示范。Llama 2 强调的是示范质量与规模小，也不是课程。因此把「课程 SFT」写成业界标准会过度声称。它是工程旋钮：当长度方差与任务族方差大、且诊断发现简单题被带坏时再打开。打开后要防止第二段把第一段冲掉——这又回到遗忘与对齐税：第二段学习率应更小，或混入第一段样本做回放。</p><p>自动难度分类器会过时。新的教师模型更啰嗦，旧的长度阈值会把几乎全部合成数据标成难，课程退化成「先人写后人写不完的合成」。应定期抽检桶的题面，而不是锁死 token 分位数。多语言上，同一绝对长度在不同语言对应不同信息量，应按语言分桶再比分位数。</p><p><span class="marginnote">评测不要只报一个混合集分数。课程是否有用，看简单遵循是否保住、难题是否上升。只用很难的竞赛集调课程，会把模型推回「凡事长推理」，简单集上的税会被忽略。</span></p><p>课程也不能替代 <a href="/llm/human-vs-synthetic-instruct">人写与合成的字段配比</a>。把人写金标全放在阶段一、合成全放在阶段二，阶段二可能把口吻改回教师。金标应在两段都出现。难度轴与来源轴是二维表，不是一条链。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令课程规定的是训练过程中各难度桶的混合比序列；它不是新损失，也不是 InstructGPT 原论文的必要步骤。</li><li>「难」要用多信号代理，并抽检；不要单用长度或教师损失，以免把啰嗦当成难、把套话当成易。</li><li>可运行的两段：先短格式与金标立住 chat 条件，再提高多轮、多约束与可检验推理的采样率；安全样本全程保下限。</li><li>LIMA 式静态高质量混合物在强基座上可以不需要课程；课程在小模型、长度方差大、合成噪声高时更值得做。</li><li>难例应晚见，不应删掉；否则覆盖失败，课程退化成过度清洗。</li><li>Self-Instruct / OpenHermes 生成器不会自动按课程出题，合成后必须再分层。</li><li>出处：Bengio 等，Curriculum Learning，2009（一般策略）；指令实践对照 Ouyang 等 InstructGPT、Zhou 等 LIMA、Wang 等 Self-Instruct。无独立「指令课程」权威论文，不编造。</li></ul>',16))])}const T=s(A,[["render",p]]);export{g as __pageData,T as default};
